def build():
    expected = {week for week in range(22, 45) if week not in (26, 31, 36, 41)}
    scenes = []
    for lang, material in (("lb", LB), ("da", DA)):
        if set(material) != expected:
            raise ValueError(f"Missing A2 weeks for {lang}: {expected ^ set(material)}")
        for week, title, goal, question, answers, writing_prompt in TOPICS:
            lines, reading, written, vocabulary = material[week]
            sid = f"{lang}-a2-w{week:02d}"

            def shuffled(values, suffix):
                options = list(values)
                random.Random(sid + suffix).shuffle(options)
                return options, options.index(values[0])

            heard, heard_answer = shuffled([lines[3][1], lines[1][1], lines[0][1]], "listen")
            choices, correct = shuffled(answers, "read")
            scenes.append({
                "id": sid, "lang": lang, "level": "A2", "week": week,
                "course_week": week, "title": title, "goal": goal, "setup": goal,
                "dialogue": [{"speaker": i % 2, "text": text, "es": es}
                             for i, (text, es) in enumerate(lines)],
                "listening": {"prompt": "¿Qué responde la última persona?", "choices": heard,
                              "answer": heard_answer},
                "turns": [{"prompt": lines[i][0], "es": f"Responde: {lines[i+1][1]}",
                           "model": lines[i+1][0], "model_es": lines[i+1][1],
                           "accepted": [], "tip": "Escucha el modelo y responde con una frase completa."}
                          for i in (0, 2)],
                "reading": {"text": reading, "prompt": question,
                            "choices": choices, "answer": correct},
                "writing": {"prompt": writing_prompt, "model": written,
                            "rubric": "Da la información solicitada con frases claras y corteses."},
                "exercises": [{"kind": "vocabulary", "prompt": f"¿Cómo se dice «{es}» en esta escena?",
                               "answer": text, "explanation": f"{text} = {es}."}
                              for text, es in vocabulary],
                "editorial_status": "pendiente de revisión por hablante competente",
            })
    output = ROOT / "content/a2-expansion.json"
    output.write_text(json.dumps(scenes, ensure_ascii=False, indent=1) + "\n")
    print(f"{output}: {len(scenes)} new A2 scenes")


if __name__ == "__main__":
    build()
